function ApplyVersusSpeedBoost(float Multiplier, float Duration)
{
    if (Role != ROLE_Authority || bVersusDead)
        return;
    Multiplier = FClamp(Multiplier, 1.0, 2.0);
    Duration = FClamp(Duration, 0.1, 30.0);
    VersusSpeedMultiplier = Multiplier;
    VersusSpeedBoostEndTime = Level.TimeSeconds + Duration;
    ApplyVersusSpeedLocally(Multiplier);
    ClientApplyVersusSpeed(Multiplier, VersusSpeedBoostEndTime);
    Log("HPVersusSpeedBoost ON pawn=" $ string(self)
        $ " multiplier=" $ string(Multiplier)
        $ " end=" $ string(VersusSpeedBoostEndTime));
}

simulated function bool IsVersusSpeedBoosted()
{
    if (VersusSpeedBoostEndTime > 0.0
        && VersusSpeedBoostEndTime <= Level.TimeSeconds)
    {
        if (Role == ROLE_Authority)
            ClearVersusSpeedBoost("ExpiredQuery");
        else
        {
            VersusSpeedMultiplier = 1.0;
            VersusSpeedBoostEndTime = 0.0;
            ApplyVersusSpeedLocally(1.0);
        }
        return False;
    }
    return VersusSpeedMultiplier > 1.01
        && VersusSpeedBoostEndTime > Level.TimeSeconds;
}

function ClearVersusSpeedBoost(string Reason)
{
    if (Role != ROLE_Authority)
        return;
    VersusSpeedMultiplier = 1.0;
    VersusSpeedBoostEndTime = 0.0;
    ApplyVersusSpeedLocally(1.0);
    ClientApplyVersusSpeed(1.0, 0.0);
    Log("HPVersusSpeedBoost OFF pawn=" $ string(self) $ " reason=" $ Reason);
}

simulated function ApplyVersusSpeedLocally(float Multiplier)
{
    if (Multiplier > 1.01)
    {
        if (!bVersusSpeedBaseCaptured)
        {
            VersusSavedGroundSpeed = GroundSpeed;
            VersusSavedGroundRunSpeed = GroundRunSpeed;
            VersusSavedDirectMoveSpeed = VersusDirectMoveSpeed;
            bVersusSpeedBaseCaptured = True;
        }
        GroundSpeed = VersusSavedGroundSpeed * Multiplier;
        GroundRunSpeed = VersusSavedGroundRunSpeed * Multiplier;
        VersusDirectMoveSpeed = VersusSavedDirectMoveSpeed * Multiplier;
    }
    else if (bVersusSpeedBaseCaptured)
    {
        GroundSpeed = VersusSavedGroundSpeed;
        GroundRunSpeed = VersusSavedGroundRunSpeed;
        VersusDirectMoveSpeed = VersusSavedDirectMoveSpeed;
        bVersusSpeedBaseCaptured = False;
    }
}

function ClientApplyVersusSpeed(float Multiplier, float EndTime)
{
    VersusSpeedMultiplier = Multiplier;
    VersusSpeedBoostEndTime = EndTime;
    ApplyVersusSpeedLocally(Multiplier);
}

