function Vector GetVersusPickupCenter()
{
    local HPVersusStart S;
    local Vector Center;
    local int Count;

    foreach AllActors(Class'HPVersusStart', S)
    {
        if (!S.bEnabled)
            continue;
        Center += S.Location;
        Count++;
    }
    if (Count > 0)
        Center = Center / float(Count);
    return Center;
}

function SpawnVersusPickups()
{
    local Vector Center;
    local Vector Offset;

    if (Role != ROLE_Authority)
        return;
    Center = GetVersusPickupCenter();

    Offset.X = -120.0;
    if (VersusHealthPickupA == None)
        VersusHealthPickupA = Spawn(
            Class'HPVersusHealthPickup',,, Center + Offset, rot(0,0,0));
    Offset.X = 120.0;
    if (VersusHealthPickupB == None)
        VersusHealthPickupB = Spawn(
            Class'HPVersusHealthPickup',,, Center + Offset, rot(0,0,0));
    Offset.X = 0.0;
    Offset.Y = 150.0;
    if (VersusSpeedPickup == None)
        VersusSpeedPickup = Spawn(
            Class'HPVersusSpeedPickup',,, Center + Offset, rot(0,0,0));

    Log("HPVersusPickups spawned healthA=" $ string(VersusHealthPickupA)
        $ " healthB=" $ string(VersusHealthPickupB)
        $ " speed=" $ string(VersusSpeedPickup)
        $ " center=" $ string(Center));
}

function ResetVersusPickups()
{
    if (VersusHealthPickupA == None
        || VersusHealthPickupB == None
        || VersusSpeedPickup == None)
        SpawnVersusPickups();
    if (VersusHealthPickupA != None)
        VersusHealthPickupA.ResetVersusPickup();
    if (VersusHealthPickupB != None)
        VersusHealthPickupB.ResetVersusPickup();
    if (VersusSpeedPickup != None)
        VersusSpeedPickup.ResetVersusPickup();
}

function bool GetVersusProbePlayers(out HPVersusHarry A, out HPVersusHarry B)
{
    local Pawn P;
    local HPVersusHarry H;

    for (P = Level.PawnList; P != None; P = P.NextPawn)
    {
        H = HPVersusHarry(P);
        if (H == None || H.Player == None)
            continue;
        if (A == None)
            A = H;
        else if (H != A)
        {
            B = H;
            return True;
        }
    }
    return False;
}

